import{_ as e,o as a,c as r,a0 as s}from"./chunks/framework.BTg7EidG.js";const m=JSON.parse('{"title":"The Bestiary","description":"","frontmatter":{},"headers":[],"relativePath":"guide/bestiary.md","filePath":"guide/bestiary.md"}'),n={name:"guide/bestiary.md"};function i(o,t,d,h,l,u){return a(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="the-bestiary" tabindex="-1">The Bestiary <a class="header-anchor" href="#the-bestiary" aria-label="Permalink to &quot;The Bestiary&quot;">​</a></h1><p>The alchemists of old did not stop at metals. Their creations — and their escapes — still walk the world.</p><h2 id="creature-lairs" tabindex="-1">Creature lairs <a class="header-anchor" href="#creature-lairs" aria-label="Permalink to &quot;Creature lairs&quot;">​</a></h2><p>Five great lairs stand in the wilds, each heavily warded and each home to one of the great creatures:</p><table tabindex="0"><thead><tr><th>Lair</th><th>Creature</th><th>Fights like</th></tr></thead><tbody><tr><td>Golem Foundry</td><td><strong>Brass Golem</strong></td><td>An anvil with fists — huge, armored, slow</td></tr><tr><td>Salamander Vent</td><td><strong>Salamander</strong></td><td>A walking furnace — searing ranged fire</td></tr><tr><td>Basilisk Pit</td><td><strong>Basilisk</strong></td><td>The crowned serpent — venom at speed</td></tr><tr><td>Quicksilver Well</td><td><strong>Quicksilver Elemental</strong></td><td>Living mercury — faster than any rider</td></tr><tr><td>Chimera Vats</td><td><strong>Chimera</strong></td><td>Three beasts stitched into one fury</td></tr></tbody></table><p>Capture a lair and you may hire its creature — for a fortune up front and a <strong>ruinous daily gold upkeep</strong>. Miss a day&#39;s pay and the creature <strong>rampages</strong>: it mauls its own party for half their health, then abandons you. Feed your monsters.</p><h2 id="the-wilds" tabindex="-1">The Wilds <a class="header-anchor" href="#the-wilds" aria-label="Permalink to &quot;The Wilds&quot;">​</a></h2><p>Packs of <strong>Homunculi</strong> — vat-spill given legs, the little horrors of the wastes — roam the world and hunt any party they find, sometimes with an escaped creature among them. They belong to no guild, take no gifts, and cannot be tamed.</p><h2 id="the-beastmaster" tabindex="-1">The Beastmaster <a class="header-anchor" href="#the-beastmaster" aria-label="Permalink to &quot;The Beastmaster&quot;">​</a></h2><p>A city grown to level 3 with a keeper working its Tavern attracts a <strong>Beastmaster</strong> — a trapper you can hire into a party. When their party defeats a wild pack, each downed <em>creature</em> has an even chance of being taken alive and joining you (upkeep and all). Homunculi are never worth keeping; the Beastmaster won&#39;t even try.</p>',10)])])}const p=e(n,[["render",i]]);export{m as __pageData,p as default};
